 npc:{
  sova:{n:"السيدة بومة",hi:["أوه، مرحباً! أنا السيدة بومة، أمينة المكتبة. عيد ميلاد مجيد!","أضعت نظارتي والآن أقرأ الكتب مقلوبة. هل رأيتها؟ أظن أنني كنت أتمشى في الحديقة…"],wait:"النظارة في مكان ما في الحديقة. ابحث قرب البركة!",
   thanks:"أوه! عادت الحروف إلى أماكنها! شكراً لمساعدتك. وبالمناسبة، طلب المساعدة شجاعة أيضاً: أنا طلبتها منك. خذ بطاقة سحرية."},
  boroda:{n:"المدير لحية-حتى-الأصابع",hi:["أهلاً بك في مدرستنا، وعيد ميلاد مجيد! أنا المدير.","في مدرستنا يمكن لكل واحد أن يكون نفسه. أخبرني ماذا تحب، حتى لو كان غريباً؟"],
   opts:["الغناء في الحمّام بأعلى صوت 🎤","جمع الحصى المضحكة 🪨","الرقص مع قطتي 🐈"],
   thanks:"رائع! الغريب هو مجرد شيء مميز. لا تخف أن تكون نفسك، فنحن نحبك لذلك. خذ بطاقة."},
  petryk:{n:"التلميذ بيتريك",hi:["مرحباً! أنا بيتريك، هذه سنتي الثالثة هنا.","نسيت فطوري! أعطني كل حبوبك!"],wait:"بضع حبات فقط… هناك الكثير منها في كل المدرسة!",
   optsBoundary:"أستطيع أن أعطيك 3 وأحتفظ بالباقي 🙂",optsAll:"أعطِه كل شيء",
   thanksBoundary:"هذا عادل! شكراً لأنك قلت بصدق كم تستطيع أن تعطي. هكذا يجب. خذ أفضل بطاقة عندي!",
   thanksAll:"أوه، وماذا عنك؟ أشياؤك مهمة أيضاً! خذها، سآخذ 3 فقط. في المرة القادمة يمكنك أن تقول: «هذا ما أستطيع أن أعطيه، والباقي لي». خذ بطاقة!"},
  gudzyk:{n:"الشبح زرّ",hi:["بووو! هل يمكنني أن أخيفك مرة أخرى؟ بوو!"],opts:["لا أحب أن يخيفني أحد. هيا نلعب الغميضة بدلاً من ذلك؟","توقف من فضلك. هذا مزعج لي."],
   heard:"أوه، جيد أنك أخبرتني! لم أكن أعرف. لن أخيفك بعد الآن. اسمع، أضعت زرّي، تدحرج إلى مكان ما في المطبخ…",wait:"زرّي في المطبخ. إنه صغير ومستدير مثلي!",
   thanks:"زرّي! الآن عباءتي تُغلق! شكراً لأنك قلت لي «توقف» بدل أن تهرب. خذ بطاقة، شفافة قليلاً، لكنها حقيقية."},
  romashka:{n:"البستانية أقحوانة",hi:["مرحباً يا شمس! أنا أقحوانة. قل لي، كيف تشعر اليوم؟"],opts:["سعيد 😊","حزين قليلاً 😔","غاضب 😠","لا أعرف 🤷"],
   feel:["الفرح مثل الشمس للأزهار. شاركه!","أن تحزن أمر طبيعي. الأزهار أيضاً تحني رؤوسها أحياناً، ثم تمتد نحو الشمس من جديد.","أن تغضب أمر طبيعي أيضاً. يمكنك أن تتنفس بعمق مثل زهرة، وأن تقول بالكلمات ما الذي يزعجك.","«لا أعرف» إجابة صادقة أيضاً. المشاعر تختبئ أحياناً مثل البذور في التراب."],
   task:"شكراً لأنك أخبرتني. والآن ساعدني: أزهاري عطشى. اذهب إلى كل أصيص واضغط E. هناك ثلاثة.",wait:"لم تشرب كل الأزهار بعد. ثلاثة أصص في الحديقة!",
   thanks:"الأزهار تتلألأ! وأنا أيضاً! خذ بطاقة برائحة النعناع."},
  pyrizhok:{n:"الطاهي فطيرة",hi:["من جاء على الرائحة؟ أنا الطاهي فطيرة! أخبز فطيرة عيد الميلاد!","بالأمس أحرقت الفطيرة. لا بأس: الخطأ مسموح، سأخبز واحدة جديدة! أحضر لي 5 حبات للحشوة."],wait:"أحتاج 5 حبات للفطيرة.",
   thanks:"الفطيرة صارت هشة مثل غيمة! خذ بطاقة، ما زالت دافئة."},
  murchyk:{n:"القط مورتشيك",hi:["مياو.","(ينظر إليك مورتشيك كأنه ينتظر منذ زمن أن تداعبه. اضغط E لتداعبه.)"],
   thanks:"خررر. أحضر لك مورتشيك بطاقة بين أسنانه. مبللة قليلاً، لكنها من القلب."},
  trener:{n:"المدرب قفّاز",hi:["أهلاً يا بطل! أنا المدرب قفّاز!","أنهِ التمارين الأربعة على الحُصر: القفز، والضغط، والقرفصاء، والجري في المكان! واستمع إلى جسمك: إذا تعبت، فالراحة تمرين أيضاً."],wait:"لم تنتهِ كل التمارين بعد. ابحث عن الحُصر في الصالة!",
   thanks:"يا لها من قوة! أنت الآن أكثر ساحر رياضي في المدرسة! خذ بطاقة البطل."}
 }
